/**
 * 唯一鉴权入口 `can()` 与列表可见性作用域 `visibilityScope()`（T2 权限实现）
 *
 * ===========================================================================
 * 冻结与归属声明
 * ===========================================================================
 *
 * 契约决策 I-9「共享文件冻结清单」规定：`can()` / `visibilityScope()` 签名的
 * 唯一修改人是**权限模块负责人（成员 2，负责 T2.1–T2.8 / M3）**。
 *
 * 但 T2.x 开工前，`T3.x`（US-03）、`T1.7`、`T5.8` 等任务全部**硬依赖**该入口
 * （基线 §4.10 明确列为硬依赖）。若空等，Sprint 会退化为串行瀑布。
 *
 * 本文件从 T0 最小骨架接管，下游模块继续通过同一入口进行权限判定。
 * 最初骨架的目的是让下游模块**从一开始就调用真入口**，
 * 而不是在自己代码里散落 `if (role === 'PM')`。
 *
 * **函数签名严格按契约决策 I-5 / I-6，不得改动**；成员 2 接管时只替换内部实现，
 * 下游调用方零改动。
 * ===========================================================================
 */
import type { PrismaClient } from '@prisma/client'
import type {
  Action,
  Decision,
  ObjectRef,
  ProjectRole,
  Scope,
  VisibilityObjectType,
} from '../../shared/types.js'

/** 写类动作：MEMBER / VIEWER 执行时返回 403（对象可见，但操作不允许）。 */
const WRITE_ACTIONS: ReadonlySet<Action> = new Set<Action>([
  'project.manage_members',
  'project.close',
  'requirement.write',
  'task.write',
  'sensitivity.manage',
])

function deny(status: 403 | 404, code: 'FORBIDDEN' | 'NOT_FOUND'): Decision {
  return { allow: false, status, code }
}

/**
 * 本入口实际用到的 Prisma delegates 的**窄 `Pick`**（C 在 #24 的请求，2026-10-18）。
 *
 * 为什么不用 `PrismaClient`：`can()` / `visibilityScope()` 需要在**同一事务内**被复用
 * （#32 受控应用路径），而 `Prisma.TransactionClient` 不满足 `PrismaClient` 的完整形状。
 * 改成只要求用到的 delegates 后：
 *   - `PrismaClient`（根客户端）与 `Prisma.TransactionClient` **结构上都满足**；
 *   - `can()` / `visibilityScope()` 的**调用语义与返回不变**，既有调用方零改动；
 *   - 本入口仍然**只读数据库、不调其他模块 service**（契约 I-9）。
 *
 * 注意：`task/rules.ts` 的 `assertTaskAssignment` 签名放宽由 ROLE-C 在其登记窗口内自行
 * 完成（B 不改 `task/` 业务文件）。
 */
export type AuthzDb = Pick<
  PrismaClient,
  | 'project'
  | 'businessGoal'
  | 'userActivity'
  | 'userStory'
  | 'task'
  | 'risk'
  | 'projectMember'
  | 'objectVisibility'
>

/**
 * 按 `ObjectRef` **现查**目标对象，取得其真实的 `projectId` 与敏感状态。
 *
 * 契约决策 I-5 约束 1：`can()` 必须自己按 id 加载目标对象，调用方无法通过传入
 * `isSensitive` / `visibleMemberIds` 等字段影响判定结果。这里必须保留该性质。
 */
async function loadTarget(
  prisma: AuthzDb,
  ref: ObjectRef,
): Promise<{ projectId: string; isSensitive: boolean } | null> {
  switch (ref.kind) {
    case 'project': {
      const p = await prisma.project.findUnique({
        where: { id: ref.projectId },
        select: { id: true },
      })
      return p ? { projectId: p.id, isSensitive: false } : null
    }
    case 'goal': {
      const g = await prisma.businessGoal.findUnique({
        where: { id: ref.objectId },
        select: { projectId: true },
      })
      // 业务目标不参与敏感白名单（Sprint 1 只有 story / task 可标敏感）
      return g ? { projectId: g.projectId, isSensitive: false } : null
    }
    case 'activity': {
      const a = await prisma.userActivity.findUnique({
        where: { id: ref.objectId },
        select: { projectId: true },
      })
      return a ? { projectId: a.projectId, isSensitive: false } : null
    }
    case 'story': {
      const s = await prisma.userStory.findUnique({
        where: { id: ref.objectId },
        select: { projectId: true, isSensitive: true },
      })
      return s ? { projectId: s.projectId, isSensitive: s.isSensitive } : null
    }
    case 'task': {
      const t = await prisma.task.findUnique({
        where: { id: ref.objectId },
        select: { projectId: true, isSensitive: true },
      })
      return t ? { projectId: t.projectId, isSensitive: t.isSensitive } : null
    }
    case 'risk': {
      // #30 风险台账：按 riskId 现查**真实** projectId（不信任调用方传入的 projectId）。
      // 敏感：风险继承所关联任务的可见性（业务口径见 `permissions.risk-status-flow`）；
      // 这里只把真实值带出来供后续判定参考，**不**把 `risk` 加入第 4 条的
      // ObjectVisibility 对象类型（第 4 条仅覆盖 story / task，不扩展）。
      const r = await prisma.risk.findUnique({
        where: { id: ref.riskId },
        select: { projectId: true, task: { select: { isSensitive: true } } },
      })
      return r ? { projectId: r.projectId, isSensitive: r.task?.isSensitive ?? false } : null
    }
    default:
      return null
  }
}

/** 读取调用者在该项目中的角色；非成员返回 null。 */
async function roleIn(
  prisma: AuthzDb,
  actorUserId: string,
  projectId: string,
): Promise<ProjectRole | null> {
  const m = await prisma.projectMember.findUnique({
    where: { projectId_userId: { projectId, userId: actorUserId } },
    select: { role: true },
  })
  return m ? (m.role as ProjectRole) : null
}

/**
 * 唯一鉴权入口。
 *
 * 判定顺序（短路，命中即返回）—— 契约决策 I-5 约束 3：
 *   1. 目标对象不存在                       → 404（不泄漏对象是否存在）
 *   2. actor 不是该项目的成员                → 404（一切动作；不泄漏项目是否存在）
 *   3. actor.role === PM                    → 允许（含敏感对象）
 *   4. 目标敏感且 actor 不在白名单 → 404（含 read）
 *   4.5 条件性动作 `task.progress` / `task.accept`：VIEWER → 403；按对象关系（负责人 / 验收人）放行，否则 403
 *   4.6 条件性动作 `risk.flow`：VIEWER → 403；`ownerUserId` = 调用者放行，否则 403
 *   5. 写类动作且 actor.role ∈ {MEMBER, VIEWER} → 403（对象可见，403 不泄漏任何东西）
 *   5.5 `risk.write` 且 actor.role === VIEWER → 403（风险台账对项目成员开放，VIEWER 只读）
 *   6. 其余                                 → 允许
 *
 * 契约决策 I-9：本函数**只读数据库，不调用其他模块的 service**。
 */
export function createAuthorization(prisma: AuthzDb) {
  async function can(actorUserId: string, action: Action, ref: ObjectRef): Promise<Decision> {
    // 第 1 条：目标对象不存在 → 404
    const target = await loadTarget(prisma, ref)
    if (!target) return deny(404, 'NOT_FOUND')

    // 第 2 条：非项目成员 → 404（一切动作）
    const role = await roleIn(prisma, actorUserId, target.projectId)
    if (role === null) return deny(404, 'NOT_FOUND')

    // 第 3 条：PM 允许一切（含敏感对象）
    if (role === 'PM') return { allow: true }

    // 第 4 条：仅 story/task 支持对象级敏感；直接按真实目标 id 查白名单。
    if (target.isSensitive && (ref.kind === 'story' || ref.kind === 'task')) {
      const entry = await prisma.objectVisibility.findUnique({
        where: { objectType_objectId_userId: {
          objectType: ref.kind, objectId: ref.objectId, userId: actorUserId,
        } },
        select: { projectId: true },
      })
      if (!entry || entry.projectId !== target.projectId) return deny(404, 'NOT_FOUND')
    }

    // 第 4.5 条（US-08）：两个「条件性动作」——负责人可推进自己的任务，验收人可验收。
    // 它们不是「写类动作一律 403」，而是按**对象关系**判定，因此必须在第 5 条之前处理。
    // 单独查这两个字段，避免改动 loadTarget 的既有契约（其它动作完全不受影响）。
    if (ref.kind === 'task' && (action === 'task.progress' || action === 'task.accept')) {
      // ★ VIEWER 本轮为全项目只读（契约 I-5 第 3 条）。即使 PM 把某个 VIEWER 指为
      //   任务负责人或验收人，也不得因此让它获得写能力。
      if (role === 'VIEWER') return deny(403, 'FORBIDDEN')
      const relation = await prisma.task.findUnique({
        where: { id: ref.objectId },
        select: { ownerUserId: true, acceptorUserId: true },
      })
      if (!relation) return deny(404, 'NOT_FOUND')
      if (action === 'task.progress' && relation.ownerUserId === actorUserId) return { allow: true }
      if (action === 'task.accept' && relation.acceptorUserId === actorUserId) return { allow: true }
      return deny(403, 'FORBIDDEN')
    }

    // 第 4.6 条（#30 风险状态流转，2026-10-18 项目负责人确认 `permissions.risk-flow-guard`）：
    //   与第 4.5 条同型的**对象关系判定** —— 成员只能流转 `ownerUserId` = 本人的风险。
    //   PM 已在第 3 条放行；VIEWER 全项目只读，显式 403；其他人一律 403。
    //   业务层不得再私写角色判断（公共层就绪前 A 侧 fail-closed 403，就此放开）。
    if (ref.kind === 'risk' && action === 'risk.flow') {
      if (role === 'VIEWER') return deny(403, 'FORBIDDEN')
      const relation = await prisma.risk.findUnique({
        where: { id: ref.riskId },
        select: { ownerUserId: true },
      })
      if (!relation) return deny(404, 'NOT_FOUND')
      if (relation.ownerUserId === actorUserId) return { allow: true }
      return deny(403, 'FORBIDDEN')
    }

    // 第 5 条：写类动作对 MEMBER / VIEWER → 403
    if (WRITE_ACTIONS.has(action)) return deny(403, 'FORBIDDEN')

    // 第 5.5 条（#30 风险台账，2026-10-18 项目负责人确认）：风险写操作对项目成员开放，
    //   `MEMBER` 落到第 6 条放行；`VIEWER` 全项目只读，这里显式 403（不泄漏对象内容）。
    //   敏感继承按 #30 的方案由风险模块自行处理，本入口不扩展 ObjectVisibility 的对象类型。
    if (action === 'risk.write' && role === 'VIEWER') return deny(403, 'FORBIDDEN')

    // 第 6 条：其余允许
    return { allow: true }
  }

  /**
   * 列表可见性作用域。
   *
   * 契约决策 I-6 要求：列表查询**必须在查询层过滤**（追加 `id IN (:ids)`），
   * 禁止「取出全量再在内存中过滤」——后者会在统计计数上泄漏敏感对象的存在性
   * （违反 AC-US-02-06「不泄漏存在性」）。
   *
   * 使用约定：
   *   mode === 'all'    → 查询不加可见性条件
   *   mode === 'subset' → 查询追加 id IN (:ids)；ids 为空则列表返回空集合
   *
   * 非 PM 只得到「非敏感对象 + 自己被指定的敏感对象」的 id。
   */
  async function visibilityScope(
    actorUserId: string,
    projectId: string,
    objectType: VisibilityObjectType,
  ): Promise<Scope> {
    const role = await roleIn(prisma, actorUserId, projectId)

    // 非成员：不可见任何对象（返回空集合，而非抛错——调用方已由 can() 拦过一道）
    if (role === null) return { mode: 'subset', ids: [] }

    // PM 无需过滤
    if (role === 'PM') return { mode: 'all' }

    const whitelisted = await prisma.objectVisibility.findMany({
      where: { projectId, objectType, userId: actorUserId },
      select: { objectId: true },
    })
    const ids = whitelisted.map(row => row.objectId)
    const rows = objectType === 'story'
      ? await prisma.userStory.findMany({
        where: { projectId, OR: [{ isSensitive: false }, { id: { in: ids } }] },
        select: { id: true },
      })
      : await prisma.task.findMany({
        where: { projectId, OR: [{ isSensitive: false }, { id: { in: ids } }] },
        select: { id: true },
      })
    return { mode: 'subset', ids: rows.map(row => row.id) }
  }

  return { can, visibilityScope }
}

export type Authorization = ReturnType<typeof createAuthorization>

// 数据模型（冻结）—— 权威来源：接口契约决策 I-7
//
// 三条 SQLite 特有硬约束（决策 I-0 / I-7）：
//   1. 枚举列全部为 String。Prisma 在 SQLite 上不支持原生 `enum`，写了会直接报错；
//      取值合法性由 `src/shared/validation.ts` 的 Zod 枚举保证，数据库层不做约束。
//   2. `planStart` / `planEnd` 为 String（'YYYY-MM-DD'），与接口契约完全一致；
//      `createdAt` 为 DateTime，序列化层负责转 ISO 8601 UTC 字符串。
//   3. 删除保护全部用 `onDelete: Restrict`（`ProjectMember` 除外，用 `Cascade`）。
//
// 注意：本文件与契约决策 I-7 的 Prisma schema 逐字对应，禁止单方面修改。

datasource db {
  provider = "sqlite"
  url      = env("DATABASE_URL") // "file:./dev.db"
}

generator client {
  provider = "prisma-client-js"
}

model User {
  id           String   @id @default(uuid())
  account      String   @unique
  displayName  String
  passwordHash String
  createdAt    DateTime @default(now())

  // 会话令牌（决策 I-8 认证约定：不透明随机串、存库校验、不使用 JWT）。
  // 只存 SHA-256 哈希，不存明文；sessionTokenExpiresAt 为 ISO 8601 UTC 字符串。
  sessionTokenHash      String? @unique
  sessionTokenExpiresAt String?

  memberships   ProjectMember[]
  ownedProjects Project[]          @relation("ProjectOwner")
  ownedTasks    Task[]             @relation("TaskOwner")
  acceptedTasks Task[]             @relation("TaskAcceptor")
  visibility    ObjectVisibility[]
  // US-09（工单 #29）：这个人执行过的验收（反向关系，见文件末尾 AcceptanceRecord）
  acceptances   AcceptanceRecord[] @relation("AcceptanceActor")
  // US-10（工单 #30）：这个人负责的风险（反向关系，见文件末尾 Risk）
  ownedRisks    Risk[]             @relation("RiskOwner")
  // US-06（工单 #26）：这个人负责的里程碑（反向关系，见文件末尾 Milestone）
  ownedMilestones Milestone[]      @relation("MilestoneOwner")
}

model Project {
  id          String   @id @default(uuid())
  name        String
  description String?
  ownerUserId String
  // US-10（工单 #30）：项目生命周期。'ACTIVE' | 'CLOSED'；关闭前的阻断校验在本票模块。
  // 故意不进共享 `ProjectView`（#30 设计：端点自己返回，避免改项目模块序列化）。
  status      String   @default("ACTIVE") // ProjectStatus
  createdAt   DateTime @default(now())

  owner      User              @relation("ProjectOwner", fields: [ownerUserId], references: [id])
  members    ProjectMember[]
  goals      BusinessGoal[]
  stories    UserStory[]
  tasks      Task[]
  visibility ObjectVisibility[]
  auditLogs  AuditLog[]
  // US-09（工单 #29）：本项目的验收记录（反向关系）
  acceptances AcceptanceRecord[]
  // US-10（工单 #30）：本项目的风险台账（反向关系，见文件末尾 Risk）
  risks       Risk[]
  // US-06（工单 #26）：本项目的里程碑 / 依赖边（反向关系，见文件末尾 Milestone / TaskDependency）
  // 注：`TaskMilestone` 只有 (taskId, milestoneId) 两列，无 projectId，故 Project 侧无对应反向关系。
  milestones       Milestone[]
  taskDependencies TaskDependency[]
}

model ProjectMember {
  projectId String
  userId    String
  role      String // ProjectRole
  joinedAt  DateTime @default(now())

  project Project @relation(fields: [projectId], references: [id], onDelete: Cascade)
  user    User    @relation(fields: [userId], references: [id], onDelete: Cascade)

  @@id([projectId, userId])
}

model BusinessGoal {
  id          String  @id @default(uuid())
  projectId   String
  name        String
  description String?
  status      String  @default("ACTIVE") // GoalStatus
  sortOrder   Int

  project    Project        @relation(fields: [projectId], references: [id], onDelete: Restrict)
  activities UserActivity[]
}

model UserActivity {
  id          String  @id @default(uuid())
  projectId   String
  goalId      String
  name        String
  description String?
  status      String  @default("ACTIVE") // GoalStatus
  sortOrder   Int

  goal    BusinessGoal @relation(fields: [goalId], references: [id], onDelete: Restrict)
  stories UserStory[]
}

model UserStory {
  id                 String   @id @default(uuid())
  projectId          String
  activityId         String
  title              String
  roleText           String
  capabilityText     String
  valueText          String
  businessValue      String
  priority           String // Priority
  status             String   @default("DRAFT") // StoryStatus
  acceptanceCriteria String?
  isSensitive        Boolean  @default(false)
  createdAt          DateTime @default(now())

  project  Project      @relation(fields: [projectId], references: [id], onDelete: Restrict)
  activity UserActivity @relation(fields: [activityId], references: [id], onDelete: Restrict)
  tasks    Task[]
}

model Task {
  id             String   @id @default(uuid())
  projectId      String
  storyId        String
  title          String
  description    String?
  ownerUserId    String
  acceptorUserId String
  planStart      String // 'YYYY-MM-DD'
  planEnd        String // 'YYYY-MM-DD'
  status         String   @default("TODO") // TaskStatus
  progress       Int? // 已完成百分比 0-100；null = 未填
  blockedReason  String? // 卡住原因，仅 status = BLOCKED 时必填
  isSensitive    Boolean  @default(false)
  createdAt      DateTime @default(now())

  project  Project   @relation(fields: [projectId], references: [id], onDelete: Restrict)
  story    UserStory @relation(fields: [storyId], references: [id], onDelete: Restrict)
  owner    User      @relation("TaskOwner", fields: [ownerUserId], references: [id], onDelete: Restrict)
  acceptor User      @relation("TaskAcceptor", fields: [acceptorUserId], references: [id], onDelete: Restrict)
  // US-09（工单 #29）：这个任务的验收记录。**故意用 Cascade**（见文件末尾的说明）：
  // 端点 29 删除任务时验收记录随库级联清理，因此不必手写清理、也不必改 test-support 的删除顺序。
  acceptances AcceptanceRecord[]
  // US-10（工单 #30）：关联到本任务的风险（用于敏感可见性继承）。
  // 任务删除时置空（SetNull）而非级联删除：风险是独立台账，不应随任务消失。
  risks       Risk[]
  // US-06（工单 #26）：本任务关联的里程碑（多对多关联表）与 FS 依赖边（反向关系）
  milestoneLinks          TaskMilestone[]
  predecessorDependencies TaskDependency[] @relation("TaskPredecessor")
  successorDependencies   TaskDependency[] @relation("TaskSuccessor")
}

// US-09 任务验收（工单 #29）—— 验收记录。
//
// 为什么需要这张表：AC5 要求「重验可再次通过 / 驳回，全过程可追溯（who / when / 结论 / 原因）」。
// 验收结论与驳回原因没有别的落点 —— `Task.blockedReason` 的语义是「卡住原因」，
// 且非 BLOCKED 态会被端点 28 清空，把它当驳回原因用属语义挪用。
//
// 状态机依据（契约门 #24 的 ROLE-A 结论 comment 6233430993）：
//   验收人把 DONE 的任务 → CLOSED（PASS）或 → DOING（REJECT，必填原因）。
//   因此 `statusBefore` 恒为 'DONE'，`statusAfter` 为 'CLOSED' 或 'DOING'；两列都存下来，
//   使这一行审计记录脱离 Task 表也读得懂（也容忍将来状态机变化）。
//
// 删除语义（本文件唯一的 Cascade）：task 用 Cascade —— 任务没了，它的验收历史就没有意义，
//   且可避免在旧模块（端点 29 的删除路径）与 test-support 的 resetDatabase 里再加清理代码。
//   project / actor 仍按仓库惯例：project 用 Cascade（与 AuditLog / ObjectVisibility 一致），
//   actor 用 Restrict（人不该被删掉而留下无主的验收记录）。
model AcceptanceRecord {
  id           String   @id @default(uuid())
  projectId    String
  taskId       String
  actorUserId  String
  conclusion   String // AcceptanceConclusion: 'PASS' | 'REJECT'
  reason       String? // 驳回时必填（服务端强制）；通过时选填
  statusBefore String // 验收前的任务状态（按 #24 结论恒为 'DONE'）
  statusAfter  String // 'CLOSED'（通过）或 'DOING'（驳回）
  createdAt    DateTime @default(now())

  project Project @relation(fields: [projectId], references: [id], onDelete: Cascade)
  task    Task    @relation(fields: [taskId], references: [id], onDelete: Cascade)
  actor   User    @relation("AcceptanceActor", fields: [actorUserId], references: [id], onDelete: Restrict)

  // 读路径：按任务查历史（旧→新）、按项目查（供 #30 / #33 的质量信号读取）
  @@index([taskId, createdAt])
  @@index([projectId, createdAt])
}

model ObjectVisibility {
  projectId  String
  objectType String // VisibilityObjectType: 'story' | 'task'
  objectId   String // 多态列，无外键（见上方特殊约定）
  userId     String

  project Project @relation(fields: [projectId], references: [id], onDelete: Cascade)
  user    User    @relation(fields: [userId], references: [id], onDelete: Cascade)

  @@id([objectType, objectId, userId])
  @@index([objectType, objectId])
  @@index([projectId, objectType])
}

// US-10 风险台账（工单 #30）—— 项目风险的落点。
//
// 为什么需要这张表：AC3 要求「风险支持三级 + 四态，非法值拒绝」，AC7 要求「敏感风险
// 不计入无权者的总数与清单」；项目模块没有任何字段能承载风险台账。
//
// 口径来源（契约门 #24 的 ROLE-A 结论，2026-10-18 人工确认）：
//   - 三级：高 / 中 / 低；四态：未处理 / 处理中 / 已解决 / 已关闭；
//     线上取值与 Zod 枚举由 `src/modules/risk/` 定义（本文件的 String 列不约束枚举，
//     与仓库既有惯例一致：枚举合法性由 `src/shared/validation.ts` / 本域校验保证）。
//   - 权限：`risk.write` = PM + MEMBER（VIEWER 一律 403 只读，见 permissions.ts 第 5.5 条）；
//     「风险状态四态流转是否限 PM、MEMBER 能否改 status / 重开」由 ROLE-A 在业务层按 #30 口径定，
//     本文件与 permissions.ts 只保证「MEMBER 可写、VIEWER 不可写」这一层。
//   - 敏感风险继承所关联任务的敏感可见性，**不扩展** `VisibilityObjectType`。
//
// 删除语义：project → Restrict（与 Task / UserStory 等业务对象一致，项目不应被删掉而留下孤儿风险）；
//   owner → Restrict（人不该被删掉而留下无主风险）；task → SetNull（风险独立于任务存在）。
model Risk {
  id          String   @id @default(uuid())
  projectId   String
  title       String
  description String?
  level       String // RiskLevel: 'HIGH' | 'MEDIUM' | 'LOW'
  status      String   @default("OPEN") // RiskStatus: 'OPEN' | 'IN_PROGRESS' | 'RESOLVED' | 'CLOSED'
  ownerUserId String
  taskId      String? // 可选关联任务（敏感可见性继承的入口）
  resolution  String?
  createdAt   DateTime @default(now())
  updatedAt   DateTime @updatedAt

  project Project @relation(fields: [projectId], references: [id], onDelete: Restrict)
  owner   User    @relation("RiskOwner", fields: [ownerUserId], references: [id], onDelete: Restrict)
  task    Task?   @relation(fields: [taskId], references: [id], onDelete: SetNull)

  // 读路径：按项目 + 状态列清单；按负责人 / 任务查关联
  @@index([projectId, status])
  @@index([ownerUserId])
  @@index([taskId])
}

model AuditLog {
  id          String   @id @default(uuid())
  projectId   String
  actorUserId String
  action      String
  objectType  String
  objectId    String
  before      String?
  after       String?
  createdAt   DateTime @default(now())

  project Project @relation(fields: [projectId], references: [id], onDelete: Cascade)
}

// US-06 甘特图（工单 #26）—— 里程碑、任务—里程碑关联、FS 依赖边。
//
// 为什么需要这三张表：AC1 要求同一视图展示需求 / 任务 / 里程碑，AC4 要求任务可关联里程碑
// 并汇总，AC5/AC6 要求仅 FS 依赖、拒绝自环 / 越项目边。既有 9 张表没有任何字段能承载
// 里程碑、任务—里程碑多对多或任务间依赖，故本票新增。
//
// 枚举列全部为 String（SQLite 无原生 enum，与文件头第 1 条一致）：
//   TaskDependency.type 本期仅接受 'FS'，其余值由写入层拒绝（见设计 §4.2）。
//
// 删除语义理由：
//   Milestone.projectId → Restrict：与 Task / UserStory 等业务对象一致，项目不应被删掉而留下孤儿里程碑。
//   Milestone.ownerUserId → Restrict：人不该被删掉而留下无主里程碑。
//   TaskMilestone 两端 → Cascade：关联行只是任务与里程碑之间的连接，任一端消失即失去意义。
//   TaskDependency.projectId → Restrict：本项目不再存在时，边不应留下孤儿。
//   TaskDependency 两端 → Restrict：删除任务不静默丢边（会影响旧 DELETE /tasks/:taskId，见设计 §3.2）。
model Milestone {
  id          String   @id @default(uuid())
  projectId   String
  name        String
  dueDate     String // 'YYYY-MM-DD'（自然日，Asia/Shanghai）
  ownerUserId String? // 可选负责人；里程碑可无单独负责人（通知口径）
  createdAt   DateTime @default(now())

  project Project          @relation(fields: [projectId], references: [id], onDelete: Restrict)
  owner   User?            @relation("MilestoneOwner", fields: [ownerUserId], references: [id], onDelete: Restrict)
  tasks   TaskMilestone[]

  @@index([projectId])
  @@index([ownerUserId])
}

// 任务—里程碑多对多关联（设计 §3.1 候选 A）：不侵入 Task 表，天然支持一个任务关联多个里程碑。
model TaskMilestone {
  taskId      String
  milestoneId String

  task      Task      @relation(fields: [taskId], references: [id], onDelete: Cascade)
  milestone Milestone @relation(fields: [milestoneId], references: [id], onDelete: Cascade)

  @@id([taskId, milestoneId])
  @@index([milestoneId])
}

model TaskDependency {
  id                String   @id @default(uuid())
  projectId         String // 冗余项目边界，便于同项目校验与过滤
  predecessorTaskId String
  successorTaskId   String
  type              String   @default("FS") // 本期仅接受 'FS'，写入层拒绝其他值
  createdAt         DateTime @default(now())

  project     Project @relation(fields: [projectId], references: [id], onDelete: Restrict)
  predecessor Task    @relation("TaskPredecessor", fields: [predecessorTaskId], references: [id], onDelete: Restrict)
  successor   Task    @relation("TaskSuccessor", fields: [successorTaskId], references: [id], onDelete: Restrict)

  @@unique([predecessorTaskId, successorTaskId, type])
  @@index([projectId])
  @@index([predecessorTaskId])
  @@index([successorTaskId])
}

/**
 * 共享契约 —— 类型与枚举（冻结）
 *
 * 权威来源：`docs/sprint1-spec-interface-contract.md`
 *   - 决策 I-1 线上格式与展示标签分离
 *   - 决策 I-2 共享类型定义
 *   - 决策 I-3 统一响应信封
 *   - 决策 I-4 错误码表
 *
 * 文件所有权（决策 I-0 / I-9）：`src/shared/` 为冻结区，唯一修改人是技术负责人。
 * 前后端引用同一份定义，不得各自声明。
 *
 * 阅读约定：`?` 表示可选字段；所有 id 为 string；所有时间戳为 ISO 8601 UTC 字符串；
 * 所有 `planStart` / `planEnd` 为 `'YYYY-MM-DD'` 字符串。
 */

// ---------------------------------------------------------------------------
// 枚举（决策 I-1）
//
// 接口陷阱（必须显式处理）：GoalStatus / StoryStatus / TaskStatus 三者都存在
// 取值 `DONE`，但语义不同。它们必须是三个**独立**的类型别名，禁止复用同一个
// 类型别名，也禁止把三者的状态值互相传递。
// ---------------------------------------------------------------------------

/** 项目角色。线上常量：PM / MEMBER / VIEWER；界面标签：项目经理 / 项目成员 / 管理者 */
export type ProjectRole = 'PM' | 'MEMBER' | 'VIEWER'

/** 业务目标与用户活动的状态。界面标签：进行中 / 已完成 */
export type GoalStatus = 'ACTIVE' | 'DONE'

/** 用户故事的状态。界面标签：待规划 / 规划中 / 已完成 */
export type StoryStatus = 'DRAFT' | 'PLANNING' | 'DONE'

/** 用户故事优先级。线上常量与界面标签同为 P0 / P1 / P2 */
export type Priority = 'P0' | 'P1' | 'P2'

/** 任务状态。界面标签：未开始 / 进行中 / 已完成 */
export type TaskStatus = 'TODO' | 'DOING' | 'BLOCKED' | 'SUSPENDED' | 'DONE' | 'CLOSED'

/** 敏感可见性作用的对象类型（多态列，无法建真实外键，见决策 I-7） */
export type VisibilityObjectType = 'story' | 'task'

// ---------------------------------------------------------------------------
// 基础形状（决策 I-2）
// ---------------------------------------------------------------------------

/** 用户简要信息，内嵌在任务响应、成员列表等处 */
export type UserBrief = { id: string; account: string; displayName: string }

export type Project = {
  id: string
  name: string
  description: string | null
  ownerUserId: string
  createdAt: string
}

/** 项目详情：在 Project 之上附加「当前调用者在该项目中的角色」 */
export type ProjectView = Project & { myRole: ProjectRole }

export type ProjectMemberView = {
  userId: string
  role: ProjectRole
  joinedAt: string
  user: UserBrief
}

export type BusinessGoal = {
  id: string
  projectId: string
  name: string
  description: string | null
  status: GoalStatus
  sortOrder: number
}

export type UserActivity = {
  id: string
  projectId: string
  goalId: string
  name: string
  description: string | null
  status: GoalStatus
  sortOrder: number
}

export type UserStory = {
  id: string
  projectId: string
  activityId: string
  title: string
  roleText: string
  capabilityText: string
  valueText: string
  businessValue: string
  priority: Priority
  status: StoryStatus
  acceptanceCriteria: string | null
  isSensitive: boolean
  createdAt: string
}

export type Task = {
  id: string
  projectId: string
  storyId: string
  title: string
  description: string | null
  ownerUserId: string
  acceptorUserId: string
  planStart: string
  planEnd: string
  status: TaskStatus
  /** 已完成百分比（0-100）；null 表示还没填 */
  progress: number | null
  /** 卡住原因；仅 status = BLOCKED 时必填，其余状态应为 null */
  blockedReason: string | null
  isSensitive: boolean
  createdAt: string
}

/** 任务响应内嵌负责人与验收人的简要信息，前端无需再发一次用户查询 */
export type TaskView = Task & { owner: UserBrief; acceptor: UserBrief }

// ---------------------------------------------------------------------------
// 层级树节点（GET /projects/:id/goals 的响应元素）
// ---------------------------------------------------------------------------

export type StoryNode = UserStory
export type ActivityNode = UserActivity & { stories: StoryNode[] }
export type GoalNode = BusinessGoal & { activities: ActivityNode[] }

// ---------------------------------------------------------------------------
// 敏感可见性（PUT .../sensitivity 的请求与响应）
// ---------------------------------------------------------------------------

export type SensitivityInput = { isSensitive: boolean; visibleMemberIds: string[] }

export type SensitivityView = {
  objectType: VisibilityObjectType
  objectId: string
  isSensitive: boolean
  visibleMemberIds: string[]
}

// ---------------------------------------------------------------------------
// 响应信封（决策 I-3）
// ---------------------------------------------------------------------------

/** 单个资源：HTTP 2xx，响应体即资源本身，不额外套壳 */
export type ItemResponse<T> = T

/** 列表：统一包装为 { items: T[] } */
export type ListResponse<T> = { items: T[] }

/** 失败：HTTP 4xx / 5xx，响应体固定为 ErrorResponse */
export type ErrorResponse = {
  error: {
    code: ErrorCode
    /** 面向人的提示，可直接展示 */
    message: string
    details?: Array<{ field: string; code: FieldErrorCode }>
  }
}

// ---------------------------------------------------------------------------
// 错误码表（决策 I-4）
// ---------------------------------------------------------------------------

/**
 * 顶层错误码。
 *   - INTERNAL_ERROR(500) 未抛 AppError 的未知异常（决策 I-2b 要求 500；
 *     契约 I-4 表未单列该码，此处为满足「未知异常一律转 500」并保持统一信封所必需的补齐）
 */
export type ErrorCode =
  | 'UNAUTHENTICATED' // 401 未登录或凭证失效
  | 'FORBIDDEN' // 403 对象可见，但该操作不允许
  | 'NOT_FOUND' // 404 对象不存在，或对调用者不可见
  | 'VALIDATION_FAILED' // 422 字段校验失败
  | 'CONFLICT' // 409 状态冲突
  | 'INTERNAL_ERROR' // 500 未预期的服务端异常（响应体不含堆栈）

/** 字段级错误码，位于 details[].code */
export type FieldErrorCode =
  | 'REQUIRED' // 必填缺失或纯空白
  | 'TOO_LONG' // 超出长度上限
  | 'INVALID_FORMAT' // 格式非法
  | 'INVALID_VALUE' // 枚举取值非法
  | 'DUPLICATE' // 唯一性冲突
  | 'USER_NOT_FOUND' // 账号对应的用户不存在
  | 'NOT_PROJECT_MEMBER' // 目标用户 / 被指定人不是本项目成员
  | 'ACCEPTOR_EQUALS_OWNER' // 验收人与负责人为同一人
  | 'END_BEFORE_START' // 计划结束早于计划开始
  | 'INSUFFICIENT_MEMBERS' // 项目成员不足 2 人
  | 'SELF_REMOVAL_FORBIDDEN' // 不能移除自己
  | 'LAST_PM' // 不能移除或降级最后一个项目经理
  | 'CROSS_PROJECT_REF' // 引用了其他项目的对象
  | 'HAS_CHILDREN' // 仍有下级对象，禁止删除

/** 字段级错误条目，由 Zod issue 映射而来（见 shared/validation.ts） */
export type FieldError = { field: string; code: FieldErrorCode }

// ---------------------------------------------------------------------------
// 鉴权入口类型（契约决策 I-5 / I-6）
//
// 【本次补录】契约决策 I-5 把 `Action` / `ObjectRef` / `Decision` 作为 `can()`
// 签名的组成部分**明文给出**，决策 I-6 同样给出 `Scope`；但 `shared/types.ts`
// 此前只落地了决策 I-1 / I-2 / I-3 / I-4 的类型，**遗漏这四个**。
// 后果：任何模块想按契约调用 `can()`，都会因「模块没有导出成员 Action」而编译失败，
// 即「统一鉴权入口」在类型层面无法被调用。
//
// 现按契约原文补录（字段与取值逐一对应契约，未自行增删）。这些类型属冻结件，
// 改动需走契约变更流程；本次仅为补齐契约**已定义却未被写入**的内容。
// ---------------------------------------------------------------------------

/** `can()` 的动作集合（决策 I-5）。 */
export type Action =
  | 'task.progress' // 更新任务状态 / 进度（负责人可对自己的任务执行）
  | 'task.accept' // 验收：DONE -> CLOSED 或驳回回 DOING
  | 'project.read' // 读取项目及其下需求与任务
  | 'project.manage_members' // 增删成员、改角色
  | 'requirement.write' // 业务目标 / 用户活动 / 用户故事的增删改
  | 'task.write' // 任务的增删改
  | 'sensitivity.manage' // 设置敏感标记与可见成员
  | 'risk.write' // 风险台账的增删改（项目成员可写，VIEWER 只读；见权限注释第 5.5 条）
  | 'risk.flow' // 风险状态流转（含重开）：PM 全部；MEMBER 仅自己负责的风险；VIEWER 403（见权限注释第 4.6 条）
  | 'project.close' // 关闭 / 重开项目（仅 PM；关闭前的阻断校验由风险 / 仪表盘模块实现）

/**
 * `can()` 的目标引用（决策 I-5）。
 *
 * 调用方**只传 id，不传任何权限相关字段** —— 否则越权就变成了改一个请求体字段的事。
 */
export type ObjectRef =
  | { kind: 'project'; projectId: string }
  | { kind: 'goal'; projectId: string; objectId: string }
  | { kind: 'activity'; projectId: string; objectId: string }
  | { kind: 'story'; projectId: string; objectId: string }
  | { kind: 'task'; projectId: string; objectId: string }
  // #30 风险台账（2026-10-18 项目负责人确认）：状态流转需按**风险归属**判定，
  // 故引用用 `riskId`（与其它分支的 `objectId` 同义，但字段名与业务语义一致）。
  | { kind: 'risk'; projectId: string; riskId: string }

/**
 * `can()` 的判定结果（决策 I-5）。
 *
 * 关键：**由 `can()` 直接给出 status 与 code**，调用方不得自行判断 403 还是 404。
 * 这消除了同一越权行为在不同端点产生不同状态码的可能。
 */
export type Decision =
  | { allow: true }
  | { allow: false; status: 403 | 404; code: 'FORBIDDEN' | 'NOT_FOUND' }

/**
 * 列表可见性作用域（决策 I-6）。
 *
 * `mode === 'all'` → 查询不加可见性条件；
 * `mode === 'subset'` → 查询追加 `id IN (:ids)`，ids 为空则列表返回空集合。
 */
export type Scope = { mode: 'all' } | { mode: 'subset'; ids: string[] }

/**
 * US-04 故事看板（GitHub #25，本地 #17）—— 只读聚合服务。
 *
 * 设计依据：`docs/role-b-board-design.md`（§3 列与卡片字段、§4 读路径、§6 权限矩阵）。
 * 响应字段由主代理冻结（见 `./types.ts`）。
 *
 * ===========================================================================
 * 本批（#17）只做只读聚合，刻意不做的事
 * ===========================================================================
 *
 * - **不跨模块调 service**（契约决策 I-9）：不 import `requirement` / `project` /
 *   `task` 的 service，自己查 Prisma 并按本模块类型组装（与
 *   `src/modules/workload/service.ts`、`src/modules/gantt/service.ts` 同范式）。
 * - **可见性进查询层**（契约决策 I-6）：`visibilityScope(actor, projectId, 'story')`
 *   的结果并入 `where`（`all` → 不加条件；`subset` → `id IN (…)`）；`count` 与
 *   `findMany` **共用同一 `where`**，禁止内存过滤 / 内存计数（会泄漏存在性）。
 * - **卡片不含 `isSensitive`**：过滤在查询层完成，列表不再回传敏感标记。
 * - **排序沿用既有源码口径** `createdAt asc, id asc`（端点 10，`requirement/service.ts`），
 *   不新造排序键。
 * - **不做写路径**：不新增 PATCH / POST，不判断角色、不新增 `Action`。
 */
import type { Prisma, PrismaClient } from '@prisma/client'
import { createAuthorization } from '../authz/permissions.js'
import type { Scope, StoryStatus } from '../../shared/types.js'
import {
  BOARD_COLUMN_ROW_LIMIT,
  BOARD_STATUS_ORDER,
  type BoardCardItem,
  type BoardColumn,
  type BoardView,
} from './types.js'

/** `visibilityScope` 的作用域 → 对外的口径标签：`all` 只可能是 PM。 */
function scopeLabelOf(scope: Scope): BoardView['basis']['scopeLabel'] {
  return scope.mode === 'all' ? '全项目' : '可见范围'
}

/**
 * 单列查询的**共用 `where`**：可见性条件与状态条件进同一个 `where`（决策 I-6）。
 *
 * `count` 与 `findMany` 必须传入**同一个** `where` 对象，否则 AC5「敏感不展示、
 * 计数与列表一致」会失配。
 */
function columnWhere(projectId: string, status: StoryStatus, scope: Scope): Prisma.UserStoryWhereInput {
  return {
    projectId,
    status,
    ...(scope.mode === 'subset' ? { id: { in: scope.ids } } : {}),
  }
}

/** 卡片取数形状：只取契约列出的 7 个字段，**不含 `isSensitive`**。 */
const CARD_SELECT = {
  id: true,
  title: true,
  priority: true,
  status: true,
  activity: { select: { name: true, goal: { select: { name: true } } } },
} as const

/**
 * 组装故事看板视图（`GET /projects/:projectId/board`）。
 *
 * 调用方（路由层）须已通过 `can(actorUserId, 'project.read', { kind: 'project', projectId })`。
 * 三列固定顺序 `DRAFT, PLANNING, DONE`；空列也返回（`count=0, items=[], truncated=false`）。
 */
export async function buildBoardView(
  prisma: PrismaClient,
  actorUserId: string,
  projectId: string,
): Promise<BoardView> {
  const { visibilityScope } = createAuthorization(prisma)
  const scope = await visibilityScope(actorUserId, projectId, 'story')

  const columns: BoardColumn[] = await Promise.all(
    BOARD_STATUS_ORDER.map(async (status) => {
      // count 与 findMany 共用同一 where（决策 I-6）。
      const where = columnWhere(projectId, status, scope)
      // 多取 1 行只用于判定截断；count 仍是精确值，不由行数反推。
      const [count, rows] = await Promise.all([
        prisma.userStory.count({ where }),
        prisma.userStory.findMany({
          where,
          orderBy: [{ createdAt: 'asc' }, { id: 'asc' }],
          take: BOARD_COLUMN_ROW_LIMIT + 1,
          select: CARD_SELECT,
        }),
      ])

      const truncated = rows.length > BOARD_COLUMN_ROW_LIMIT
      const shown = truncated ? rows.slice(0, BOARD_COLUMN_ROW_LIMIT) : rows
      const items: BoardCardItem[] = shown.map((row) => ({
        id: row.id,
        title: row.title,
        priority: row.priority,
        status: row.status as StoryStatus,
        activityName: row.activity.name,
        goalName: row.activity.goal.name,
      }))

      return { status, count, truncated, items }
    }),
  )

  return {
    projectId,
    basis: { scopeLabel: scopeLabelOf(scope) },
    columns,
  }
}

/**
 * 路由集中注册表（冻结，决策 I-0 / I-9 / I-11）
 *
 * 各模块只导出路由插件，由本文件集中注册；数据库依赖通过 RouteContext 注入。
 */
import type { FastifyInstance } from 'fastify'
import type { PrismaClient } from '@prisma/client'
import { registerAuthRoutes } from './auth/plugin.js'
import { registerAcceptanceRoutes } from './modules/acceptance/plugin.js'
import { registerSensitivityRoutes } from './modules/authz/plugin.js'
import { registerProjectRoutes } from './modules/project/plugin.js'
import { registerTaskRoutes } from './modules/task/routes.js'
import { registerWorkloadRoutes } from './modules/workload/plugin.js'
import { registerGanttRoutes } from './modules/gantt/plugin.js'
import { registerBoardRoutes } from './modules/board/plugin.js'
import { registerWorkbenchRoutes } from './modules/workbench/plugin.js'
import { registerRequirementRoutes } from './modules/requirement/plugin.js'

export type RouteContext = {
  prisma: PrismaClient
}

export function registerRoutes(app: FastifyInstance, context: RouteContext): void {
  app.get('/health', async () => ({ status: 'ok' }))

  // M1 身份与会话（端点 1–2）
  registerAuthRoutes(app, context)

  // M2 项目与成员（端点 3–9）
  registerProjectRoutes(app, context)

  // M3 授权与敏感可见（端点 23、30）
  registerSensitivityRoutes(app, context)

  // M4 需求层级（端点 10–22）
  registerRequirementRoutes(app, context)

  // M5 任务（端点 24–29）：24 故事任务列表 / 25 创建任务 / 26 按项目列任务 /
  // 27 任务详情 / 28 部分更新 / 29 删除。
  // 注意：端点 30（PUT /tasks/:taskId/sensitivity）唯一归属 M3，由上方
  // registerSensitivityRoutes 注册；M5 不得再注册，否则 Fastify 抛
  // FST_ERR_DUPLICATED_ROUTE 使整个应用无法构建。
  registerTaskRoutes(app, context)

  // A / US-08 个人工作台（工单 #28）：GET /me/workbench。
  // 该端点不在 Sprint 1 契约的 30 个端点内，属本阶段新增（见 docs/us-08-workbench-api.md）。
  registerWorkbenchRoutes(app, context)

  // A / US-09 任务验收（工单 #29）：POST /tasks/:taskId/acceptance、
  // GET /tasks/:taskId/acceptances、GET /projects/:projectId/acceptance-queue。
  // 同样不在 Sprint 1 契约的 30 个端点内，属本阶段新增（见 docs/us-09-acceptance-api.md）。
  // 注意：这两个路径与 M3 已注册的 PUT /tasks/:taskId/sensitivity 后缀不同，
  // 不与 M2 的 /projects/... 前缀冲突（Fastify 同 method+path 重复注册会抛
  // FST_ERR_DUPLICATED_ROUTE 使整个应用无法构建）。
  registerAcceptanceRoutes(app, context)

  // B / US-07 成员任务图与负载（工单 #27）：GET /projects/:projectId/workload、
  // GET /projects/:projectId/workload/:userId。
  // 同样不在 Sprint 1 契约的 30 个端点内，属本阶段新增（见 docs/role-b-workload-design.md）。
  // 只读聚合：复用既有 project.read 权限，不新增 Action。
  registerWorkloadRoutes(app, context)

  // B / US-06 甘特图（工单 #26）：GET /projects/:projectId/gantt。
  // 不在 Sprint 1 契约的 30 个端点内，属本阶段新增（见 docs/role-b-gantt-design.md）。
  // 只读聚合：复用既有 project.read，不新增 Action；里程碑 / 依赖写入属后续批次（#12，待公共事件端口）。
  registerGanttRoutes(app, context)

  // B / US-04 故事看板（工单 #25）：GET /projects/:projectId/board（只读三列）。
  // 不在 Sprint 1 契约的 30 个端点内，属本阶段新增（见 docs/role-b-board-design.md）。
  // 状态写入仍走既有 PATCH /stories/:storyId（端点 21），本模块不建镜像写入口。
  registerBoardRoutes(app, context)
}
